                            else fprintf(out, "\\x%02x", c);
                        }
                        fprintf(out, "\n");
                        fflush(out);
                    }
                }
            }
            free(buf);
        }

        close(mem_fd);
        fclose(maps_f);
    }

    closedir(proc_dir);
    fprintf(out, "[memreader4] done\n");
    fclose(out);
